"""Auto-generated model and system cards (Markdown) from an eval report.

Structure follows "Model Cards for Model Reporting" (Mitchell et al., 2019):
details, intended use, factors, metrics, evaluation data, caveats.
"""
from __future__ import annotations

from datetime import datetime, timezone

from . import LABELS

DESCRIPTIONS = {
    "rules-v1": "Keyword-rule classifier. No training data.",
    "nb-v1": "Multinomial naive Bayes on unigrams and bigrams, Laplace smoothing, trained on `intent_train.jsonl`.",
    "nb-small": "Same as nb-v1 but trained on only 24 examples. Exists to demonstrate a failing gate.",
}


def _ci(m: dict, name: str) -> str:
    c = m["ci95"][name]
    return f"{c['point']:.3f} [{c['low']:.3f}, {c['high']:.3f}]"


def model_card(report: dict, system: str, review_stats: dict | None = None, generated_at: str | None = None) -> str:
    m = report["systems"][system]
    ts = report["testset"]
    comp = report["comparison"]
    when = generated_at or datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M UTC")
    lines = [
        f"# Model card: {system}",
        "",
        f"_Generated by `llm-eval card` on {when} from `reports/eval.json`. Do not edit by hand._",
        "",
        "## Model details",
        f"- **System:** `{system}`. {DESCRIPTIONS.get(system, 'External or custom system.')}",
        f"- **Task:** single-label intent classification of customer-support tickets into {', '.join(f'`{x}`' for x in LABELS)}.",
        "- **Owner:** llm-eval-lab (learning project).",
        "",
        "## Intended use",
        "- Routing synthetic support tickets in this repository's demos.",
        "- **Out of scope:** real customer data, non-English text, any automated decision about a person.",
        "",
        "## Evaluation data",
        f"- **Test set:** `{ts['name']}` (version `{ts['version']}`, {ts['n']} examples, sha256 `{ts['sha256'][:16]}…`), pinned in `dvc.lock`.",
        "- Synthetic, template-generated tickets. Slices: `easy` (keyword-bearing) and `hard` (paraphrased or mixed intent).",
        "",
        "## Metrics (95% bootstrap CI)",
        "",
        "| Metric | Value [95% CI] |",
        "|---|---|",
        f"| Accuracy | {_ci(m, 'accuracy')} |",
        f"| Macro F1 | {_ci(m, 'macro_f1')} |",
        f"| Macro precision | {_ci(m, 'macro_precision')} |",
        f"| Macro recall | {_ci(m, 'macro_recall')} |",
        "",
        "| Class | Precision | Recall | F1 | Support |",
        "|---|---|---|---|---|",
    ]
    for c, v in m["per_class"].items():
        lines.append(f"| {c} | {v['precision']:.3f} | {v['recall']:.3f} | {v['f1']:.3f} | {v['support']} |")
    lines += ["", "Accuracy by slice: " + ", ".join(f"`{k}` {v:.3f}" for k, v in m["accuracy_by_slice"].items()), ""]
    if system in (comp["baseline"], comp["candidate"]):
        other = comp["baseline"] if system == comp["candidate"] else comp["candidate"]
        mc = comp["mcnemar"]
        pf = comp["permutation"]["macro_f1"]
        lines += [
            f"## Comparison with `{other}` (paired, same {ts['n']} examples)",
            f"- McNemar: {comp['baseline']} right / {comp['candidate']} wrong = {mc['b']}, the reverse = {mc['c']}, exact p = {mc['p_exact']:.4g}.",
            f"- Macro-F1 delta ({comp['candidate']} − {comp['baseline']}) = {pf['delta']:+.3f}, 95% CI [{pf['ci_low']:+.3f}, {pf['ci_high']:+.3f}], permutation p = {pf['p_value']:.4g}.",
            "",
        ]
    if review_stats and review_stats.get("pairwise_kappa"):
        lines += ["## Human review", f"- {review_stats['items']} items queued ({', '.join(f'{k}: {v}' for k, v in review_stats['reasons'].items())})."]
        for p in review_stats["pairwise_kappa"]:
            lines.append(f"- Cohen's kappa {p['raters'][0]} vs {p['raters'][1]}: {p['kappa']:.3f} ({p['band']}, n={p['n']}).")
        lines.append("")
    lines += [
        "## Caveats",
        "- The test set is synthetic and small; CIs are wide on per-class numbers and the `hard` slice.",
        "- High scores here say nothing about real tickets. Re-evaluate on representative, consented data before any real use.",
        "- Bootstrap CIs treat examples as i.i.d.; template-generated examples are not fully independent.",
        "",
    ]
    return "\n".join(lines)


def system_card(report: dict) -> str:
    mt = report["mt"]
    lines = [
        "# System card: evaluation pipeline",
        "",
        "End-to-end view of what is evaluated, how, and with which known gaps.",
        "",
        "## Components",
        "| Component | Version / config |",
        "|---|---|",
        f"| Intent test set | `{report['testset']['name']}` sha256 `{report['testset']['sha256'][:16]}…` |",
        f"| Systems compared | baseline `{report['comparison']['baseline']}`, candidate `{report['comparison']['candidate']}` |",
        f"| BLEU | `{mt['signatures']['bleu']}` |",
        f"| chrF++ | `{mt['signatures']['chrf++']}` |",
        "",
        f"## MT results (EN→DE, {mt['n']} hand-written sentences)",
        "| System | BLEU | chrF++ | COMET |",
        "|---|---|---|---|",
    ]
    for s, v in mt["systems"].items():
        comet = v.get("comet")
        lines.append(f"| {s} | {v['bleu']:.2f} | {v['chrf++']:.2f} | {comet if comet is not None else 'not run'} |")
    if "paired" in mt:
        for metric, p in mt["paired"].items():
            lines.append("")
            lines.append(f"- Paired bootstrap {metric}: delta (sys_b − sys_a) {p['delta']:+.2f}, 95% CI [{p['ci_low']:+.2f}, {p['ci_high']:+.2f}], p ≈ {p['p_value']:.3g}.")
    lines += [
        "",
        "## Known gaps",
        "- 30 MT sentences is far below what a real MT evaluation needs; treat the numbers as a worked example.",
        "- COMET is optional and is not run in CI (model download).",
        "",
    ]
    return "\n".join(lines)
